def choose_move(observation):
    # Deterministic simple heuristic with strict return of [dx, dy] in {-1,0,1}
    gw = getattr(observation, "grid_width", None)
    gh = getattr(observation, "grid_height", None)
    sp = getattr(observation, "self_position", None)
    op = getattr(observation, "opponent_position", None)

    if sp is None:
        return [0, 0]

    sx, sy = sp if isinstance(sp, (list, tuple)) and len(sp) >= 2 else (0, 0)

    # If we have a known opponent position, move away from it if adjacent
    if op is not None:
        ox, oy = op if isinstance(op, (list, tuple)) and len(op) >= 2 else (sx, sy)
        dx = sx - ox
        dy = sy - oy
        if abs(dx) <= 1 and abs(dy) <= 1:
            if dx != 0 or dy != 0:
                return [1 if dx > 0 else -1 if dx < 0 else 0,
                        1 if dy > 0 else -1 if dy < 0 else 0]

    # If there is a resource hint, try toward it
    resources = getattr(observation, "resources", None)
    if resources:
        best = None
        for r in resources:
            if isinstance(r, (list, tuple)) and len(r) >= 2:
                rx, ry = r[0], r[1]
                dist = abs(rx - sx) + abs(ry - sy)
                if best is None or dist < best[0]:
                    best = (dist, rx, ry)
        if best is not None:
            rx, ry = best[1], best[2]
            dx = 0 if rx == sx else (1 if rx > sx else -1)
            dy = 0 if ry == sy else (1 if ry > sy else -1)
            return [dx, dy]

    # Default exploration: try to move right, then down, then left, then up
    for cand in ((1, 0), (0, 1), (-1, 0), (0, -1), (0, 0)):
        dx, dy = cand
        nx, ny = sx + dx, sy + dy
        if gw is not None and (nx < 0 or ny < 0 or nx >= gw or ny >= gh):
            continue
        return [dx, dy]

    return [0, 0]
